"""An opt-in transport must not invalidate frozen legacy profile revisions."""

import copy
import json
from types import SimpleNamespace

import pytest
from doonex.model_registry import ModelRegistry, RegistryError
from doonex.models import ModelConfig
from pydantic import ValidationError

# Generated by the unmodified registry at 491bf4c. The hash is intentionally
# fixed, rather than recomputed through the serializer under test.
LEGACY_PROFILE = {
    "id": "legacy-compatible",
    "name": "Legacy compatible",
    "model": {
        "provider": "openai",
        "model_id": "doonex-offline-transport",
        "api_mode": "responses",
        "credential_env": "DOONEX_LLM_API_KEY",
        "base_url": None,
        "allow_private_http": False,
        "billing_mode": "subscription",
        "max_input_tokens": 32768,
        "max_output_tokens": 2048,
        "timeout_seconds": 60,
        "input_price_per_million": None,
        "output_price_per_million": None,
        "price_source": None,
    },
    "usage_adapter": "none",
    "revision": "593fccfe9a10e5087eb8c1ebf6abdbcd400218901e6af79228306739bb601834",
    "read_only": False,
}


@pytest.fixture
def legacy_registry(tmp_path):
    home = tmp_path / "private"
    home.mkdir(mode=0o700)
    path = home / "profiles.json"
    path.write_text(json.dumps({"schema_version": 1, "profiles": [LEGACY_PROFILE]}))
    path.chmod(0o600)
    return ModelRegistry(SimpleNamespace(home=home, model=None)), path


@pytest.mark.parametrize("explicit", [False, True])
def test_direct_transport_preserves_legacy_model_payload(explicit):
    data = copy.deepcopy(LEGACY_PROFILE["model"])
    if explicit:
        data["responses_transport"] = "direct"
    model = ModelConfig.model_validate(data)
    assert model.responses_transport == "direct"
    assert model.model_dump() == LEGACY_PROFILE["model"]
    assert json.loads(model.model_dump_json()) == LEGACY_PROFILE["model"]


def test_old_profile_revision_loads_without_migration_or_rewrite(legacy_registry):
    registry, path = legacy_registry
    original = path.read_bytes()
    profile = registry.get("legacy-compatible")
    assert profile.model_dump() == LEGACY_PROFILE
    assert profile.model.responses_transport == "direct"
    assert path.read_bytes() == original


def test_isolated_transport_creates_explicit_frozen_revision(legacy_registry):
    registry, path = legacy_registry
    original = registry.get("legacy-compatible")
    isolated = registry.save(
        "isolated",
        "Isolated",
        {
            **LEGACY_PROFILE["model"],
            "responses_transport": "isolated_direct_v1",
        },
    )
    assert isolated.model.responses_transport == "isolated_direct_v1"
    assert isolated.model.model_dump()["responses_transport"] == "isolated_direct_v1"
    assert registry.get("isolated") == isolated
    assert registry.get("legacy-compatible").model_dump() == LEGACY_PROFILE
    assert original.model_dump() == LEGACY_PROFILE
    assert json.loads(path.read_bytes())["profiles"][0] == LEGACY_PROFILE

    updated = registry.save(
        original.id,
        original.name,
        isolated.model,
        expected_revision=original.revision,
    )
    assert updated.revision != original.revision
    assert original.model_dump() == LEGACY_PROFILE


@pytest.mark.parametrize(
    "changes",
    [
        {"api_mode": "chat", "responses_transport": "isolated_direct_v1"},
        {
            "provider": "anthropic",
            "api_mode": "chat",
            "responses_transport": "isolated_direct_v1",
        },
        {"responses_transport": "automatic"},
        {"responses_transport": None},
    ],
)
def test_invalid_transport_combinations_are_rejected(changes):
    with pytest.raises(ValidationError):
        ModelConfig.model_validate({**LEGACY_PROFILE["model"], **changes})


def test_transport_cannot_be_changed_without_new_profile_revision(legacy_registry):
    registry, path = legacy_registry
    payload = json.loads(path.read_bytes())
    payload["profiles"][0]["model"]["responses_transport"] = "isolated_direct_v1"
    path.write_text(json.dumps(payload))
    original = path.read_bytes()
    with pytest.raises(RegistryError, match="版本"):
        registry.list()
    assert path.read_bytes() == original


def test_isolated_mode_without_controller_binding_cannot_fall_back(tmp_path):
    from doonex.sdk import run_session

    def forbidden(*args, **kwargs):
        pytest.fail("An unbound isolated transport must not reserve or dispatch")

    state = tmp_path / "session"
    with pytest.raises(ValueError, match="controller binding"):
        run_session(
            run_id="f4886ce8-d969-4b92-a8d3-b37ed2c538d5",
            state_dir=state,
            prompt="offline",
            model={
                **LEGACY_PROFILE["model"],
                "responses_transport": "isolated_direct_v1",
            },
            api_key="synthetic-test-key",
            before_model=forbidden,
            after_model=forbidden,
            shell=forbidden,
            on_event=forbidden,
            should_stop=forbidden,
        )
    assert not state.exists()
